#requires -Version 7.0
<#
.SYNOPSIS
Builds an offline component/dependency inventory from explicit NuGet or npm lock data.
.PARAMETER InputPath
Explicit project.assets.json, packages.lock.json, or npm package-lock v2/v3 files.
.PARAMETER AdvisoryPath
Optional schema1 records [{ecosystem,name,version,identifiers[],severity?}], source and capturedUtc.
.PARAMETER LicensePath
Optional schema1 records [{ecosystem,name,version,license}], source and capturedUtc.
.PARAMETER OnlineDotNetAudit
Explicitly authorizes installed dotnet CLI project/feed query with --no-restore. Never default.
.NOTES
DevTools.ComponentInventory/1 is a documented custom SBOM, not SPDX/CycloneDX certification.
Missing license/advisory evidence is Unknown. Offline mode executes no tools/network.
Optional OutputPath must be a new file. No package installation, restore or package scripts.
Exit0 complete supplied checks pass,2 known vulnerability/hash failure,3 unknown evidence,125 input/setup.
#>
[CmdletBinding()]
param([string[]]$InputPath=@(),[string]$AdvisoryPath,[string]$LicensePath,[string]$CacheCatalogPath,[string]$CacheRoot,[switch]$OnlineDotNetAudit,[string]$ProjectPath,[string]$OutputPath,[ValidateRange(1,120)][int]$TimeoutSeconds=60,[switch]$Json)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'lib/RuntimeCommon.ps1');. (Join-Path $PSScriptRoot 'lib/WindowsDiagnosticsCommon.ps1')
$result=[ordered]@{schemaVersion=1;observedUtc=[datetime]::UtcNow.ToString('o');tool='Get-DependencyAudit';scope='Explicit supported lockfiles and supplied evidence';sbomFormat='DevTools.ComponentInventory/1';valid=$false;components=@();relationships=@();evidence=@();cache=@();onlineAudit=$null;networkAccess='NotPerformed';findings=@();error=$null;limitations=@('Custom inventory is not standards-certified SPDX/CycloneDX.','Offline lock data does not prove installed bytes or currently known vulnerability absence.','Absent advisory/license/relationship evidence remains unknown.')}
$components=[Collections.Generic.List[object]]::new();$relationships=[Collections.Generic.List[object]]::new();$findings=[Collections.Generic.List[object]]::new();$evidence=[Collections.Generic.List[object]]::new();$componentMap=@{}
function Add-Component([string]$Ecosystem,[string]$Name,[string]$Version,[string]$Source,$License=$null){
    if(-not $Name -or $Name.Length -gt 512 -or -not $Version -or $Version.Length -gt 256){throw 'Invalid component name/version.'};$key="$Ecosystem|$Name|$Version";if($componentMap.ContainsKey($key)){return $componentMap[$key]};if($components.Count -ge 20000){throw 'Component limit exceeded.'}
    $entry=@{id='component-'+$components.Count;ecosystem=$Ecosystem;name=$Name;version=$Version;license=$(if($License -is [string] -and $License){$License}else{'Unknown'});licenseEvidence=$(if($License){$Source}else{$null});advisories=@();advisoryStatus='Unknown';source=$Source};$components.Add($entry);$componentMap[$key]=$entry;return $entry
}
function Add-Relationship($From,$To,[string]$Source){if($relationships.Count -ge 100000){throw 'Relationship limit exceeded.'};$relationships.Add(@{from=$From.id;to=$To.id;type='DependsOn';evidence=$Source})}
function Get-DependencyKeys($Map){if($null -eq $Map){return};if($Map -isnot [Collections.IDictionary]){throw 'Dependency maps must be JSON objects.'};$Map.Keys}
function Same-Package($Record,$Component){$Record.ecosystem -eq $Component.ecosystem -and $Record.version -ceq $Component.version -and $(if($Component.ecosystem -eq 'NuGet'){$Record.name -ieq $Component.name}else{$Record.name -ceq $Component.name})}
function Has-Evidence($Value){$Value -is [string] -and -not [string]::IsNullOrWhiteSpace($Value) -and $Value.Trim() -notin @('Unknown','NOASSERTION','NotProvided','NotPerformed','None','N/A')}
function Read-Auxiliary([string]$File){$data=Read-DevJson $File;if($data.schemaVersion -ne 1 -or $data.records -isnot [array] -or $data.records.Count -gt 20000 -or -not $data.source -or -not $data.capturedUtc){throw 'Auxiliary evidence needs schemaVersion1, records, source and capturedUtc.'};$date=[datetime]::MinValue;if(-not [datetime]::TryParse($data.capturedUtc,[ref]$date)){throw 'Invalid evidence capture timestamp.'};foreach($record in $data.records){if($record.ecosystem -notin @('NuGet','npm') -or -not $record.name -or -not $record.version){throw 'Invalid auxiliary component identity.'}};return $data}
try{
    if($InputPath.Count -gt 16 -or (-not $InputPath.Count -and -not $OnlineDotNetAudit -and -not $CacheCatalogPath)){throw 'Provide 1-16 explicit lockfiles, an explicit online audit, or a cache catalog.'}
    foreach($input in $InputPath){$file=Get-Item -LiteralPath $input;$data=Read-DevJson $file.FullName;$source=$file.FullName
        if($data.Contains('packages') -and $data.lockfileVersion -in @(2,3)){
            if($data.packages -isnot [Collections.IDictionary] -or $data.packages.Count -gt 20000){throw 'Invalid npm packages map.'};$byPath=@{}
            foreach($path in $data.packages.Keys){$package=$data.packages[$path];if(-not $path){continue};if($package.link){$findings.Add(@{id='LinkedPackage';status='unknown';detail='Linked npm workspace content is not inspected.';path=$path});continue};$name=if($package.name){$package.name}else{($path -split '(?:^|/)node_modules/')[-1]};if(-not $package.version){$findings.Add(@{id='MissingPackageVersion';status='unknown';detail=$path});continue};$byPath[$path]=Add-Component npm $name $package.version $source $package.license}
            foreach($path in $byPath.Keys){$package=$data.packages[$path];foreach($dependency in @(Get-DependencyKeys $package.dependencies)){$candidate=$path+'/node_modules/'+$dependency;$parent=$path;$selected=$null;for($step=0;$step -lt 64;$step++){if($byPath.ContainsKey($candidate)){$selected=$byPath[$candidate];break};$marker=$parent.LastIndexOf('/node_modules/');$parent=if($marker -ge 0){$parent.Substring(0,$marker)}else{''};$candidate=if($parent){$parent+'/node_modules/'+$dependency}else{'node_modules/'+$dependency};if(-not $parent){if($byPath.ContainsKey($candidate)){$selected=$byPath[$candidate]};break}};if($selected){Add-Relationship $byPath[$path] $selected $source}else{$findings.Add(@{id='UnresolvedLockRelationship';status='unknown';component=$byPath[$path].id;dependency=$dependency})}}}
            $evidence.Add(@{path=$source;format="npm package-lock v$($data.lockfileVersion)";rootDependencies=$(if($data.packages.Contains('')){$data.packages[''].dependencies}else{$null});coverage='Package dependency maps, not runtime/installed-byte evidence'})
        }elseif($data.Contains('libraries') -and $data.Contains('targets')){
            if($data.libraries -isnot [Collections.IDictionary] -or $data.targets -isnot [Collections.IDictionary]){throw 'Invalid NuGet assets maps.'};$byKey=@{}
            foreach($key in $data.libraries.Keys){$library=$data.libraries[$key];if($library.type -ne 'package'){continue};$split=$key.LastIndexOf('/');if($split -lt 1){throw 'Invalid NuGet library identity.'};$byKey[$key]=Add-Component NuGet $key.Substring(0,$split) $key.Substring($split+1) $source}
            foreach($target in $data.targets.Keys){$targetMap=$data.targets[$target];foreach($key in $targetMap.Keys){if(-not $byKey.ContainsKey($key)){continue};foreach($dependency in @(Get-DependencyKeys $targetMap[$key].dependencies)){$matches=@($targetMap.Keys | Where-Object {($_ -split '/')[0] -ieq $dependency -and $byKey.ContainsKey($_)});if($matches.Count -eq 1){Add-Relationship $byKey[$key] $byKey[$matches[0]] "$source#$target"}else{$findings.Add(@{id='UnresolvedLockRelationship';status='unknown';component=$byKey[$key].id;dependency=$dependency;target=$target})}}}}
            $evidence.Add(@{path=$source;format='NuGet project.assets';coverage='Resolved package libraries and per-target dependency maps'})
        }elseif($data.version -eq 1 -and $data.dependencies -is [Collections.IDictionary]){
            foreach($framework in $data.dependencies.Keys){$map=$data.dependencies[$framework];$byName=@{};foreach($name in $map.Keys){if(-not $map[$name].resolved){throw 'NuGet lock entry lacks resolved version.'};$byName[$name]=Add-Component NuGet $name $map[$name].resolved "$source#$framework"};foreach($name in $map.Keys){foreach($dependency in @(Get-DependencyKeys $map[$name].dependencies)){if($byName.ContainsKey($dependency)){Add-Relationship $byName[$name] $byName[$dependency] "$source#$framework"}else{$findings.Add(@{id='UnresolvedLockRelationship';status='unknown';component=$byName[$name].id;dependency=$dependency})}}}}
            $evidence.Add(@{path=$source;format='NuGet packages.lock v1';coverage='Resolved per-framework dependencies'})
        }else{throw "Unsupported lockfile format: $source"}
    }
    $advisory=if($AdvisoryPath){Read-Auxiliary $AdvisoryPath};$licenses=if($LicensePath){Read-Auxiliary $LicensePath}
    foreach($component in $components){
        if($licenses){$records=@($licenses.records | Where-Object {Same-Package $_ $component});if($records.Count -gt 1){throw 'Duplicate/conflicting license evidence.'};if($records.Count){if($records[0].license -isnot [string] -or -not $records[0].license){throw 'License evidence must contain a nonempty license string.'};$component.license=$records[0].license;$component.licenseEvidence=@{source=$licenses.source;capturedUtc=$licenses.capturedUtc}}}
        if($advisory){$records=@($advisory.records | Where-Object {Same-Package $_ $component});if($records.Count -gt 1){throw 'Duplicate advisory coverage records.'};if($records.Count){if($records[0].identifiers -isnot [array]){throw 'Advisory records must declare identifiers arrays (empty means no findings in that supplied snapshot).'};$component.advisories=@($records);$component.advisoryStatus=if($records[0].identifiers.Count){'KnownFindings'}else{'NoFindingsInSuppliedSnapshot'};if($records[0].identifiers.Count){$findings.Add(@{id='SuppliedAdvisory';status='fail';component=$component.id;source=$advisory.source;capturedUtc=$advisory.capturedUtc})}}}
        if(-not (Has-Evidence $component.license)){$findings.Add(@{id='LicenseUnknown';status='unknown';component=$component.id})};if($component.advisoryStatus -eq 'Unknown'){$findings.Add(@{id='AdvisoryUnknown';status='unknown';component=$component.id;detail='No complete current advisory coverage was established.'})}
    }
    if($CacheCatalogPath){if(-not $CacheRoot){throw 'CacheRoot is required with CacheCatalogPath.'};$catalog=Read-DevJson $CacheCatalogPath;if($catalog.schemaVersion -ne 1 -or $catalog.entries -isnot [array] -or $catalog.entries.Count -gt 10000){throw 'Invalid cache catalog schema.'};$cache=[Collections.Generic.List[object]]::new();foreach($entry in $catalog.entries){if($entry.sha256 -notmatch '^[A-Fa-f0-9]{64}$'){throw 'Cache entry requires SHA256.'};$path=Resolve-DevContainedFile $CacheRoot $entry.path;$status=if(-not [IO.File]::Exists($path)){'fail'}elseif((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -ine $entry.sha256){'fail'}elseif(-not (Has-Evidence $entry.license) -or -not (Has-Evidence $entry.source) -or -not (Has-Evidence $entry.version) -or -not (Has-Evidence $entry.provenance)){'unknown'}else{'pass'};$cache.Add(@{path=$path;status=$status;source=$entry.source;version=$entry.version;license=$entry.license;provenance=$entry.provenance});if($status -ne 'pass'){$findings.Add(@{id='CacheVerification';status=$status;path=$path})}};$result.cache=@($cache.ToArray())}
    if($OnlineDotNetAudit){if(-not $ProjectPath){throw 'Explicit ProjectPath is required for online .NET audit.'};$project=Get-Item -LiteralPath $ProjectPath;if($project.PSIsContainer -or $project.Extension -notin @('.csproj','.fsproj','.vbproj','.sln','.slnx')){throw 'ProjectPath must name an explicit .NET project/solution.'};$dotnet=Get-Command dotnet.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1;$help=Invoke-DevBoundedProcess $dotnet.Source @('package','list','--help') $project.DirectoryName $TimeoutSeconds;if($help.ExitCode -ne 0 -or $help.Stdout -notmatch '--no-restore'){$result.onlineAudit=@{status='unsupported';exitCode=$help.ExitCode};$findings.Add(@{id='OnlineAuditUnsupported';status='unknown'})}else{$result.networkAccess='ExplicitlyRequested';$command=Invoke-DevBoundedProcess $dotnet.Source @('package','list','--project',$project.FullName,'--no-restore','--vulnerable','--include-transitive','--format','json') $project.DirectoryName $TimeoutSeconds;$output=$null;try{$output=$command.Stdout | ConvertFrom-Json -Depth 24}catch{};$result.onlineAudit=@{exitCode=$command.ExitCode;timedOut=$command.TimedOut;truncated=$command.Truncated;result=$output};if($command.ExitCode -ne 0 -or -not $output -or $command.Truncated){$findings.Add(@{id='OnlineAuditUnavailable';status='unknown'})}else{foreach($projectResult in @($output.projects)){foreach($framework in @($projectResult.frameworks)){foreach($package in @($framework.topLevelPackages)+@($framework.transitivePackages)){if(@($package.vulnerabilities).Count){$findings.Add(@{id='OnlineAdvisory';status='fail';name=$package.id;version=$package.resolvedVersion;advisories=$package.vulnerabilities})}}}}}}}
    $result.components=@($components.ToArray());$result.relationships=@($relationships.ToArray());$result.evidence=@($evidence.ToArray());$result.findings=@($findings.ToArray());$result.valid= -not @($findings | Where-Object status -in @('fail','unknown')).Count;$global:LASTEXITCODE=if(@($findings | Where-Object status -eq fail).Count){2}elseif(-not $result.valid){3}else{0}
    if($OutputPath){$output=Assert-DevNewDestination $OutputPath;$parent=Split-Path $output -Parent;if(-not [IO.Directory]::Exists($parent)){throw 'OutputPath parent must already exist.'};$stream=[IO.File]::Open($output,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$writer=[IO.StreamWriter]::new($stream);try{$writer.Write(($result | ConvertTo-Json -Depth 24))}finally{$writer.Dispose()}}finally{$stream.Dispose()}}
}catch{$result.error=$_.Exception.Message;$global:LASTEXITCODE=125}
if($Json){$result | ConvertTo-Json -Depth 24}else{[pscustomobject]$result}
